export const FREE_TIER_PROVIDER_BY_ID = Object.fromEntries(FREE_TIER_PROVIDERS.map((provider) => [provider.id, provider]));
export const FREE_TIER_MODELS_BY_PROVIDER = FREE_TIER_MODEL_RECORDS.reduce((groups, model) => {
  (groups[model.provider] ||= []).push(model);
  return groups;
}, {});
export const UNAVAILABLE_FREE_TIER_PROVIDER_IDS = new Set(FREE_TIER_PROVIDERS.filter((provider) => !provider.available).map((provider) => provider.id));

export function isFreeTierProviderAvailable(providerId) {
  return FREE_TIER_PROVIDER_BY_ID[providerId]?.available === true;
}
